(lambda _: kAssert(kEq((isInRange := lambda x: (x >= 0) and (x <= 100), isInRange(50))[-1], True)))(None)
(lambda _: kAssert(kEq((isInRange := lambda x: (x >= 0) and (x <= 100), isInRange(150))[-1], False)))(None)
(lambda _: kAssert(kEq((isEqual := lambda a, b: kEq(a, b), isEqual(5, 5))[-1], True)))(None)
(lambda _: kAssert(kEq((isEqual := lambda a, b: kEq(a, b), isEqual(5, 6))[-1], False)))(None)
(lambda _: kAssert(kEq((isTruthy := lambda x: x, isTruthy(True))[-1], True)))(None)
(lambda _: kAssert(kEq((isTruthy := lambda x: x, isTruthy(False))[-1], False)))(None)
